        [DllImport("winmm.dll")]private static extern uint waveOutGetNumDevs();[DllImport("winmm.dll")]private static extern uint waveInGetNumDevs();[DllImport("winmm.dll")]private static extern uint midiInGetNumDevs();[DllImport("winmm.dll")]private static extern uint midiOutGetNumDevs();
