        public static List<DeviceChoice> AudioOutputs(){List<DeviceChoice> a=new List<DeviceChoice>();a.Add(new DeviceChoice{Id=-1,Name="System default output"});for(uint i=0;i<waveOutGetNumDevs();i++){WaveCaps c;if(OutCaps((UIntPtr)i,out c,(uint)Marshal.SizeOf(typeof(WaveCaps)))==0)a.Add(new DeviceChoice{Id=(int)i,Name=c.Name});}return a;}
        public static List<DeviceChoice> AudioInputs(){List<DeviceChoice> a=new List<DeviceChoice>();a.Add(new DeviceChoice{Id=-1,Name="System default input"});for(uint i=0;i<waveInGetNumDevs();i++){WaveCaps c;if(InCaps((UIntPtr)i,out c,(uint)Marshal.SizeOf(typeof(WaveCaps))-4)==0)a.Add(new DeviceChoice{Id=(int)i,Name=c.Name});}return a;}
        public static List<DeviceChoice> MidiInputs(){List<DeviceChoice> a=new List<DeviceChoice>();a.Add(new DeviceChoice{Id=-1,Name="None"});for(uint i=0;i<midiInGetNumDevs();i++){MidiCaps c;if(InputCaps((UIntPtr)i,out c,(uint)Marshal.SizeOf(typeof(MidiCaps)))==0)a.Add(new DeviceChoice{Id=(int)i,Name=c.Name});}return a;}
        public static List<DeviceChoice> MidiOutputs(){List<DeviceChoice> a=new List<DeviceChoice>();a.Add(new DeviceChoice{Id=-1,Name="None (internal instruments only)"});for(uint i=0;i<midiOutGetNumDevs();i++){MidiOutCaps c;if(OutputCaps((UIntPtr)i,out c,(uint)Marshal.SizeOf(typeof(MidiOutCaps)))==0)a.Add(new DeviceChoice{Id=(int)i,Name=c.Name});}return a;}
