    internal sealed class NativeWaveBuffer:IDisposable{public IntPtr Data,Header;public int Size;public bool Queued;public NativeWaveBuffer(int bytes){Size=bytes;Data=Marshal.AllocHGlobal(bytes);Header=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(WaveHeader)));WaveHeader h=new WaveHeader{Data=Data,Length=(uint)bytes};Marshal.StructureToPtr(h,Header,false);}public WaveHeader Read(){return (WaveHeader)Marshal.PtrToStructure(Header,typeof(WaveHeader));}public void Dispose(){if(Header!=IntPtr.Zero){Marshal.FreeHGlobal(Header);Header=IntPtr.Zero;}if(Data!=IntPtr.Zero){Marshal.FreeHGlobal(Data);Data=IntPtr.Zero;}}}
    public sealed class WaveOutputStream:IAudioOutput
    {
        [StructLayout(LayoutKind.Sequential)]private struct MmTime{public uint Type,Value,Reserved;}
        [DllImport("winmm.dll")]private static extern uint waveOutOpen(out IntPtr handle,uint id,ref WaveFormat format,IntPtr callback,IntPtr instance,uint flags);
        [DllImport("winmm.dll")]private static extern uint waveOutPrepareHeader(IntPtr handle,IntPtr header,uint size);[DllImport("winmm.dll")]private static extern uint waveOutUnprepareHeader(IntPtr handle,IntPtr header,uint size);[DllImport("winmm.dll")]private static extern uint waveOutWrite(IntPtr handle,IntPtr header,uint size);[DllImport("winmm.dll")]private static extern uint waveOutReset(IntPtr handle);[DllImport("winmm.dll")]private static extern uint waveOutClose(IntPtr handle);[DllImport("winmm.dll")]private static extern uint waveOutGetPosition(IntPtr handle,ref MmTime time,uint size);
        private IntPtr _handle;private AutoResetEvent _signal=new AutoResetEvent(false);private readonly List<NativeWaveBuffer> _buffers=new List<NativeWaveBuffer>();private Thread _thread;private volatile bool _stopping;private bool _disposed;private Action<float[],int,long> _render;private readonly int _frames;private long _submitted;public event Action<Exception> Failed;
        public long FramesPlayed{get{MmTime t=new MmTime{Type=2};IntPtr h=_handle;if(h==IntPtr.Zero||waveOutGetPosition(h,ref t,(uint)Marshal.SizeOf(typeof(MmTime)))!=0)return 0;return t.Value;}}
        public WaveOutputStream(int device,int rate,int frames,Action<float[],int,long> render){_frames=frames;_render=render;WaveFormat format=WaveFormat.Pcm(rate,2);uint code=waveOutOpen(out _handle,unchecked((uint)device),ref format,_signal.SafeWaitHandle.DangerousGetHandle(),IntPtr.Zero,0x00050000);if(code!=0)throw new InvalidOperationException("Audio output could not be opened (MMRESULT "+code+"). Choose another device or sample rate.");try{for(int i=0;i<3;i++){NativeWaveBuffer b=new NativeWaveBuffer(frames*4);_buffers.Add(b);Check(waveOutPrepareHeader(_handle,b.Header,(uint)Marshal.SizeOf(typeof(WaveHeader))));}_thread=new Thread(Run){IsBackground=true,Name="Slop audio output",Priority=ThreadPriority.AboveNormal};_thread.Start();}catch{Dispose();throw;}}
