    }
    public sealed class PcmWaveWriter:IDisposable
    {
        private readonly FileStream _stream;private readonly BinaryWriter _writer;private readonly int _rate,_channels;private long _bytes;private int _lastHeader;private bool _closed;public long DataBytes{get{return _bytes;}}
        public PcmWaveWriter(string path,int rate,int channels){_rate=rate;_channels=channels;Directory.CreateDirectory(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path)));_stream=new FileStream(path,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.Read);_writer=new BinaryWriter(_stream);_writer.Write(new byte[44]);Header();_lastHeader=Environment.TickCount;}
        private void Header(){long position=_stream.Position;_stream.Position=0;_writer.Write(Encoding.ASCII.GetBytes("RIFF"));_writer.Write((uint)(36+_bytes));_writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));_writer.Write(16);_writer.Write((ushort)1);_writer.Write((ushort)_channels);_writer.Write(_rate);_writer.Write(_rate*_channels*2);_writer.Write((ushort)(_channels*2));_writer.Write((ushort)16);_writer.Write(Encoding.ASCII.GetBytes("data"));_writer.Write((uint)_bytes);_stream.Position=position;_writer.Flush();_stream.Flush(true);}
        public void Write(byte[] bytes,int count){if(_closed)throw new ObjectDisposedException("PcmWaveWriter");if(count<0||count>bytes.Length||count%(_channels*2)!=0)throw new InvalidDataException("PCM capture block is invalid.");if(_bytes+count>256L*1024*1024-44)throw new InvalidDataException("Recording reached the 256 MiB per-take limit. Captured audio remains in the finalized take.");_writer.Write(bytes,0,count);_bytes+=count;if(unchecked(Environment.TickCount-_lastHeader)>=250){Header();_lastHeader=Environment.TickCount;}}
        public void Dispose(){if(_closed)return;_closed=true;Header();_writer.Dispose();}
    }
    public sealed class WaveCaptureStream:IDisposable
    {
        [DllImport("winmm.dll")]private static extern uint waveInOpen(out IntPtr h,uint id,ref WaveFormat format,IntPtr callback,IntPtr instance,uint flags);[DllImport("winmm.dll")]private static extern uint waveInPrepareHeader(IntPtr h,IntPtr header,uint size);[DllImport("winmm.dll")]private static extern uint waveInUnprepareHeader(IntPtr h,IntPtr header,uint size);[DllImport("winmm.dll")]private static extern uint waveInAddBuffer(IntPtr h,IntPtr header,uint size);[DllImport("winmm.dll")]private static extern uint waveInStart(IntPtr h);[DllImport("winmm.dll")]private static extern uint waveInStop(IntPtr h);[DllImport("winmm.dll")]private static extern uint waveInReset(IntPtr h);[DllImport("winmm.dll")]private static extern uint waveInClose(IntPtr h);
        private IntPtr _handle;private AutoResetEvent _signal=new AutoResetEvent(false);private List<NativeWaveBuffer> _buffers=new List<NativeWaveBuffer>();private Thread _thread;private volatile bool _stopping;private bool _disposed;private PcmWaveWriter _writer;public string Path{get;private set;}public Exception Error{get;private set;}public long CapturedBytes{get;private set;}
        private Action<float[],int,int,long> _inputCallback;private int _inputChannels;
        public WaveCaptureStream(int device,int rate,int frames,string path):this(device,rate,frames,path,null,1){}
        public WaveCaptureStream(int device,int rate,int frames,string path,Action<float[],int,int,long> callback,int channels){_inputCallback=callback;_inputChannels=channels;Path=path;WaveFormat format=WaveFormat.Pcm(rate,channels);uint code=waveInOpen(out _handle,unchecked((uint)device),ref format,_signal.SafeWaitHandle.DangerousGetHandle(),IntPtr.Zero,0x50000);if(code!=0)throw new InvalidOperationException("Audio input could not be opened (MMRESULT "+code+"). Check input availability and Windows microphone access.");try{if(path!=null)_writer=new PcmWaveWriter(path,rate,channels);for(int i=0;i<4;i++){NativeWaveBuffer b=new NativeWaveBuffer(frames*channels*2);_buffers.Add(b);Check(waveInPrepareHeader(_handle,b.Header,(uint)Marshal.SizeOf(typeof(WaveHeader))));Check(waveInAddBuffer(_handle,b.Header,(uint)Marshal.SizeOf(typeof(WaveHeader))));b.Queued=true;}Check(waveInStart(_handle));_thread=new Thread(Run){IsBackground=true,Name="Slop audio capture"};_thread.Start();}catch{Dispose();throw;}}
        private static void Check(uint value){if(value!=0)throw new InvalidOperationException("Windows input capture failed (MMRESULT "+value+").");}
        private void Run(){try{bool done=false;while(!done){_signal.WaitOne(15);foreach(NativeWaveBuffer b in _buffers){if(!b.Queued)continue;WaveHeader h=b.Read();if((h.Flags&1)==0)continue;b.Queued=false;int n=(int)(h.Recorded/2*2);if(n>0){byte[] bytes=new byte[n];Marshal.Copy(b.Data,bytes,0,n);if(_writer!=null)_writer.Write(bytes,n);if(_inputCallback!=null){float[] f=new float[n/2];for(int j=0;j<f.Length;j++)f[j]=BitConverter.ToInt16(bytes,j*2)/32768f;_inputCallback(f,n/(2*_inputChannels),_inputChannels,CapturedBytes/(2*_inputChannels));}CapturedBytes+=n;}if(!_stopping){Check(waveInAddBuffer(_handle,b.Header,(uint)Marshal.SizeOf(typeof(WaveHeader))));b.Queued=true;}}if(_stopping)done=true;}}catch(Exception ex){Error=ex;}finally{if(_handle!=IntPtr.Zero){waveInStop(_handle);waveInReset(_handle);foreach(NativeWaveBuffer b in _buffers)waveInUnprepareHeader(_handle,b.Header,(uint)Marshal.SizeOf(typeof(WaveHeader)));waveInClose(_handle);_handle=IntPtr.Zero;}foreach(NativeWaveBuffer b in _buffers)b.Dispose();_buffers.Clear();if(_writer!=null){_writer.Dispose();_writer=null;}}}
        public void Dispose(){if(_disposed)return;_disposed=true;_stopping=true;if(_handle!=IntPtr.Zero){waveInStop(_handle);waveInReset(_handle);}_signal.Set();if(_thread!=null&&Thread.CurrentThread!=_thread&&!_thread.Join(5000))throw new TimeoutException("The audio capture thread did not stop.");_thread=null;if(_handle!=IntPtr.Zero){foreach(NativeWaveBuffer b in _buffers){waveInUnprepareHeader(_handle,b.Header,(uint)Marshal.SizeOf(typeof(WaveHeader)));b.Dispose();}_buffers.Clear();waveInClose(_handle);_handle=IntPtr.Zero;}if(_writer!=null){_writer.Dispose();_writer=null;}_signal.Dispose();}
    }
    public sealed class MidiInputMessage:EventArgs{public int Status,Data1,Data2;public long Timestamp;}
    public sealed class MidiInputDevice:IDisposable
    {
        private delegate void MidiCallback(IntPtr handle,uint message,IntPtr instance,UIntPtr data,UIntPtr time);
        [DllImport("winmm.dll")]private static extern uint midiInOpen(out IntPtr handle,uint device,MidiCallback callback,IntPtr instance,uint flags);[DllImport("winmm.dll")]private static extern uint midiInStart(IntPtr h);[DllImport("winmm.dll")]private static extern uint midiInStop(IntPtr h);[DllImport("winmm.dll")]private static extern uint midiInReset(IntPtr h);[DllImport("winmm.dll")]private static extern uint midiInClose(IntPtr h);
        private IntPtr _handle;private MidiCallback _callback;public event EventHandler<MidiInputMessage> MessageReceived;
        public MidiInputDevice(int device):this(device,null){}
        public MidiInputDevice(int device,EventHandler<MidiInputMessage> receiver){if(receiver!=null)MessageReceived+=receiver;_callback=Callback;uint code=midiInOpen(out _handle,(uint)device,_callback,IntPtr.Zero,0x30000);if(code!=0)throw new InvalidOperationException("MIDI input could not be opened (MMRESULT "+code+").");code=midiInStart(_handle);if(code!=0){Dispose();throw new InvalidOperationException("MIDI input could not start (MMRESULT "+code+").");}}
